import os,re,collections
root='.'
gofiles=[]
for dp,dn,fn in os.walk(root):
    if any(x in dp for x in ('graphify-out','/web/','node_modules','/.git')): continue
    for f in fn:
        if f.endswith('.go'): gofiles.append(os.path.join(dp,f))
src={f:open(f,encoding='utf8',errors='ignore').read() for f in gofiles}
# package name per file
pkg={f:(re.search(r'^package (\w+)',s,re.M).group(1) if re.search(r'^package (\w+)',s,re.M) else '') for f,s in src.items()}
decl_re=re.compile(r'^func (?:\((?P<recv>[^)]*)\)\s*)?(?P<name>[A-Za-z0-9_]+)\(',re.M)
decls=[]  # (name, recv, file, pkgdir)
for f,s in src.items():
    if not f.startswith('./internal') or f.endswith('_test.go'): continue
    for m in decl_re.finditer(s):
        decls.append((m.group('name'), (m.group('recv') or '').strip(), f))
results=[]
for name,recv,f in decls:
    pdir=os.path.dirname(f)
    ppkg=pkg[f]
    pat=re.compile(r'(?<![A-Za-z0-9_])'+re.escape(name)+r'\(')
    intra=0; cross=0; crossfiles=set(); intrafiles=set()
    for g,s in src.items():
        cnt=len(pat.findall(s))
        d=len(re.findall(r'^func (?:\([^)]*\)\s*)?'+re.escape(name)+r'\(',s,re.M))
        if os.path.dirname(g)==pdir:
            intra+=cnt-d
            if cnt-d>0: intrafiles.add(g)
        else:
            # qualified pkg.Name( or method call .Name(
            q=len(re.findall(r'(?<![A-Za-z0-9_])'+re.escape(ppkg)+r'\.'+re.escape(name)+r'\(',s))
            m2=len(re.findall(r'\.'+re.escape(name)+r'\(',s)) if recv else 0
            c=q+ (m2 if recv else 0)
            cross+=c
            if c>0: crossfiles.add(g)
    results.append((intra+cross,intra,cross,name,recv,f,len(intrafiles|crossfiles)))
results.sort(reverse=True)
for r in results[:30]:
    print(f"tot={r[0]:4d} intra={r[1]:4d} cross={r[2]:4d} files={r[6]:3d}  {'('+r[4]+') ' if r[4] else ''}{r[3]}  <- {r[5]}")
EOF
